def evaluateWithPriorities(expr, prio):
    MOD = 10 ** 9 + 7
    pr = {'+': prio[0], '-': prio[1], '*': prio[2]}
    vals = []
    ops = []

    def apply():
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '+':
            vals.append((a + b) % MOD)
        elif op == '-':
            vals.append((a - b) % MOD)
        else:
            vals.append(a * b % MOD)

    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            vals.append(int(expr[i:j]) % MOD)
            i = j
            continue
        if c == '(':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
        else:
            while ops and ops[-1] != '(' and pr[ops[-1]] >= pr[c]:
                apply()
            ops.append(c)
        i += 1
    while ops:
        apply()
    return vals[0]
